/**
 * Edge entry point: wraps the Worker generated by OpenNext (`wrangler.jsonc` → "main").
 *
 * Plain-HTTP requests to the public hosts get a 301 to HTTPS before Next.js runs. The zone's
 * "Always Use HTTPS" switch does the same, but the wrangler login token can't change zone
 * settings, so it lives in code. Without it, http:// served a 200 copy of every page: a
 * duplicate for crawlers. Local previews (localhost, http) are untouched.
 */
// Generated by `opennextjs-cloudflare build` (may not exist yet when type-checking).
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import handler from "./.open-next/worker.js";

type Ctx = { waitUntil(p: Promise<unknown>): void };
type Fetch = (request: Request, env: unknown, ctx: Ctx) => Promise<Response>;

const PUBLIC_HOST = /(^|\.)crownd\.dev$/;

/**
 * Micro-cache for public HTML (30 s, per Cloudflare colo, via the Cache API).
 * Why: on the Workers Free plan each request gets ~10 ms of CPU, and a cold Next.js render can
 * exceed it ("Worker exceeded CPU time limit" → 503). A cache hit returns before Next.js runs.
 * Only anonymous, side-effect-free pages are cached: no API, redirects, checkout or assets, and
 * never a response that sets a cookie. 30 s keeps the board effectively live.
 */
const HTML_TTL = 30;
function cacheable(request: Request, url: URL) {
  if (request.method !== "GET" || !PUBLIC_HOST.test(url.hostname)) return false;
  const p = url.pathname;
  return !(p.startsWith("/api/") || p.startsWith("/go/") || p.startsWith("/_next/") || p.includes("/checkout/") || p === "/analytics");
}

const edge = {
  async fetch(request: Request, env: unknown, ctx: Ctx) {
    const url = new URL(request.url);
    if (url.protocol === "http:" && PUBLIC_HOST.test(url.hostname)) {
      url.protocol = "https:";
      url.hostname = "crownd.dev"; // www → apex in the same hop
      return Response.redirect(url.toString(), 301);
    }
    const next = handler as { fetch: Fetch };
    if (!cacheable(request, url) || typeof caches === "undefined") return next.fetch(request, env, ctx);

    const cache = (caches as unknown as { default: Cache }).default;
    const hit = await cache.match(request);
    if (hit) {
      // The edge cache rewrites Cache-Control with the zone's Browser Cache TTL (4 h): restore the
      // page's own header so browsers never keep a stale board.
      const out = new Response(hit.body, hit);
      out.headers.set("Cache-Control", hit.headers.get("X-Page-Cache-Control") || "private, no-cache, no-store, max-age=0, must-revalidate");
      out.headers.delete("X-Page-Cache-Control");
      return out;
    }

    const res = await next.fetch(request, env, ctx);
    const type = res.headers.get("content-type") ?? "";
    if (res.status === 200 && type.includes("text/html") && !res.headers.has("set-cookie")) {
      const copy = new Response(res.clone().body, res);
      copy.headers.set("X-Page-Cache-Control", res.headers.get("cache-control") ?? "");
      copy.headers.set("Cache-Control", `public, max-age=${HTML_TTL}`);
      ctx.waitUntil(cache.put(request, copy));
    }
    return res;
  },
};

export default edge;

// Durable Object classes referenced by OpenNext's generated config must stay exported.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
